const catalog=window.RotaCatalog, resources=catalog.resources, pageSize=12;
const areas=['Todas',...catalog.areas],types=['Todos','Projeto','Estudo','Competição','Visita','Rede'];
const state={search:'',area:'Todas',type:'Todos',region:'Nordeste',uf:'CE',mode:'',focus:'',topic:'',inactive:false,includeNational:true,page:1,routeArea:null,routeUf:'CE',favorites:loadFavorites()};
const byId=new Map(resources.map(r=>[r.id,r])), $=id=>document.getElementById(id);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function normalize(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');}
const searchIndex=new Map(resources.map(r=>[r.id,normalize([r.title,r.description,r.institution,r.place,r.audience,...r.topics,...r.tags,...r.states,...r.regions].join(' '))]));
function loadFavorites(){try{const v=JSON.parse(localStorage.getItem('rota-delas-favoritos')||'[]');return new Set(Array.isArray(v)?v.filter(id=>typeof id==='string'):[]);}catch{return new Set();}}
function saveFavorites(){try{localStorage.setItem('rota-delas-favoritos',JSON.stringify([...state.favorites]));}catch{announceApp('Este navegador não permite guardar favoritos entre visitas.');}}
function announceApp(message){$('app-status').textContent=message;}
function cardMarkup(r){const saved=state.favorites.has(r.id),e=escapeHTML;return `<article class="resource-card" data-resource="${e(r.id)}"><div class="card-top"><span class="card-kind">${e(r.kind)}</span><button class="favorite-button" type="button" data-favorite="${e(r.id)}" aria-label="${saved?'Remover':'Salvar'} ${e(r.title)} ${saved?'dos':'nos'} favoritos" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><h3>${e(r.title)}</h3><div class="resource-tags"><span>${e(r.focus)}</span><span>${e(r.area)}</span>${r.topics.map(t=>`<span>${e(t)}</span>`).join('')}</div><p>${e(r.description)}</p><dl class="resource-meta"><div><dt>Instituição</dt><dd>${e(r.institution)}</dd></div><div><dt>Público</dt><dd>${e(r.audience)}</dd></div><div><dt>Formato</dt><dd>${e(r.mode)}</dd></div></dl><details class="source-details"><summary>Fonte e consulta${r.sourceStatus==='Inativo'?' · inativo na fonte':''}</summary><p>${r.sourceStatus==='Ativo'?'O diretório indica atividade; isso não confirma vagas abertas.':r.sourceStatus==='Inativo'?'O diretório marca este projeto como inativo. Registro mantido para consulta histórica.':'Datas, vagas, custos e critérios devem ser confirmados na fonte.'}</p><ul>${r.sources.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.name)} ↗</a> · consultada em ${e(s.checkedAt.split('-').reverse().join('/'))}</li>`).join('')}</ul></details><div class="card-bottom"><span>${e(r.place)}</span><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir fonte oficial de ${e(r.title)} em nova aba">Fonte oficial ↗</a></div></article>`;}
function renderFilters(id,options,key){const c=$(id);if(!c.children.length)c.innerHTML=options.map(o=>`<button type="button" data-filter="${key}" data-value="${o}" aria-pressed="false">${o}</button>`).join('');c.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(state[key]===b.dataset.value)));}
function visibleResources(){const words=normalize(state.search.trim()).split(/\s+/).filter(Boolean);return resources.filter(r=>{const national=r.scope==='Nacional';return words.every(w=>searchIndex.get(r.id).includes(w))&&(state.area==='Todas'||r.area===state.area)&&(state.type==='Todos'||r.kind===state.type)&&(!state.region||r.regions.includes(state.region)||(national&&state.includeNational))&&(!state.uf||r.states.includes(state.uf)||(national&&state.includeNational))&&(!state.mode||r.mode===state.mode)&&(!state.focus||r.focus===state.focus)&&(!state.topic||r.topics.includes(state.topic))&&(state.inactive||r.sourceStatus!=='Inativo');}).sort((a,b)=>state.uf?Number(!a.states.includes(state.uf))-Number(!b.states.includes(state.uf)):0);}
function favoriteFocus(id){const a=document.activeElement;return $(id).contains(a)?a.dataset.favorite:null;}
function restoreFavoriteFocus(id,resource){if(!resource)return;const b=[...$(id).querySelectorAll('[data-favorite]')].find(b=>b.dataset.favorite===resource);if(b)b.focus({preventScroll:true});else{$('saved-title').tabIndex=-1;$('saved-title').focus({preventScroll:true});}}
function renderCards(){const focused=favoriteFocus('cards'),all=visibleResources(),pages=Math.max(1,Math.ceil(all.length/pageSize));state.page=Math.min(state.page,pages);const start=(state.page-1)*pageSize,visible=all.slice(start,start+pageSize);$('cards').innerHTML=visible.map(cardMarkup).join('');$('cards').hidden=!all.length;$('empty-state').hidden=!!all.length;$('result-count').textContent=`${all.length} ${all.length===1?'caminho encontrado':'caminhos encontrados'}${all.length?` · exibindo ${start+1}–${start+visible.length}`:''}`;$('pagination').hidden=pages===1;$('page-status').textContent=`Página ${state.page} de ${pages}`;$('page-prev').disabled=state.page===1;$('page-next').disabled=state.page===pages;$('clear-filters').hidden=!state.search&&!state.uf&&!state.region&&!state.mode&&!state.focus&&!state.topic&&!state.inactive&&state.includeNational&&state.area==='Todas'&&state.type==='Todos';renderFilters('area-filters',areas,'area');renderFilters('type-filters',types,'type');renderTerritory();restoreFavoriteFocus('cards',focused);}
function renderSaved(){const focused=favoriteFocus('saved-cards'),saved=[...state.favorites].map(id=>byId.get(id)).filter(Boolean);$('saved-count').textContent=`${saved.length} ${saved.length===1?'item':'itens'}`;$('saved-cards').innerHTML=saved.length?saved.map(cardMarkup).join(''):'<div class="empty-saved">Toque no coração de um item para guardá-lo aqui.</div>';restoreFavoriteFocus('saved-cards',focused);}
function fillStates(id,includeAll=true){const s=$(id),value=s.value;const options=Object.entries(catalog.states).sort((a,b)=>a[1][0].localeCompare(b[1][0],'pt-BR')).filter(([uf,v])=>id!=='uf-filter'||!state.region||v[1]===state.region);s.innerHTML=(includeAll?'<option value="">'+(id==='route-uf'?'Brasil · recursos nacionais':'Todos os estados')+'</option>':'<option value="">Selecione o estado</option>')+options.map(([uf,v])=>`<option value="${uf}">${v[0]} (${uf})</option>`).join('');s.value=value;}
function renderRouteOptions(){if(!$('route-options').children.length)$('route-options').innerHTML=['Tecnologia e Computação','Ciência','Matemática'].map(a=>`<button type="button" data-route-area="${a}" aria-pressed="false">${a}</button>`).join('');$('route-options').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(state.routeArea===b.dataset.routeArea)));}
function chooseRoute(area){return area?RotaPlanner.ensure(area,state.routeUf).items:[];}
function renderRoute(){if(state.routeArea)RotaPlanner.render(state.routeArea,state.routeUf);}
function clearFilters(){Object.assign(state,{search:'',area:'Todas',type:'Todos',region:'',uf:'',mode:'',focus:'',topic:'',inactive:false,includeNational:true,page:1});$('search').value='';for(const id of ['region-filter','mode-filter','focus-filter','topic-filter'])$(id).value='';fillStates('uf-filter');$('uf-filter').value='';$('include-national').checked=true;$('include-inactive').checked=false;renderCards();$('search').focus();}

function renderTerritory(){
 const ce=state.uf==='CE'&&state.includeNational,br=!state.region&&!state.uf;
 document.querySelectorAll('[data-territory]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.territory==='ceara'?ce:br)));
 $('territory-status').textContent=state.uf?(catalog.states[state.uf][0]+(state.includeNational?' + recursos nacionais':' · iniciativas locais')):state.region?(state.region+(state.includeNational?' + recursos nacionais':'')):'Todo o Brasil';
}
function setTerritory(value){
 Object.assign(state,{region:value==='ceara'?'Nordeste':'',uf:value==='ceara'?'CE':'',includeNational:true,page:1});
 $('region-filter').value=state.region;fillStates('uf-filter');$('uf-filter').value=state.uf;$('include-national').checked=true;
 state.routeUf=value==='ceara'?'CE':'';$('route-uf').value=state.routeUf;renderCards();renderRoute();
 announceApp(value==='ceara'?'Busca no Ceará com recursos nacionais.':'Busca em todo o Brasil.');
}

function changed(){state.page=1;renderCards();}
fillStates('uf-filter');fillStates('route-uf');$('uf-filter').value='CE';$('region-filter').value='Nordeste';$('route-uf').value='CE';
$('topic-filter').innerHTML='<option value="">Todos os temas</option>'+catalog.topics.map(t=>`<option>${escapeHTML(t)}</option>`).join('');
const stats=catalog.stats;$('catalog-stats').innerHTML=`<div><strong>${stats.total}</strong><span>recursos documentados</span></div><div><strong>${stats.states}</strong><span>UFs com iniciativas locais</span></div><div><strong>${stats.regions}</strong><span>regiões representadas</span></div><div><strong>${stats.national}</strong><span>recursos de alcance nacional</span></div>`;
$('catalog-coverage').textContent=`O catálogo reúne ${stats.femaleFocus} iniciativas e recursos com foco em meninas. ${stats.total-stats.active} registros inativos ficam ocultos por padrão. É um levantamento inicial, sem cobertura completa dos estados ou medição de impacto.`;
$('search').addEventListener('input',e=>{state.search=e.target.value;changed();});
for(const [id,key] of [['region-filter','region'],['uf-filter','uf'],['mode-filter','mode'],['focus-filter','focus'],['topic-filter','topic']])$(id).addEventListener('change',e=>{state[key]=e.target.value;if(key==='region'){state.uf='';fillStates('uf-filter');$('uf-filter').value='';}changed();});
$('include-national').addEventListener('change',e=>{state.includeNational=e.target.checked;changed();});$('include-inactive').addEventListener('change',e=>{state.inactive=e.target.checked;changed();});
$('clear-filters').addEventListener('click',clearFilters);$('empty-reset').addEventListener('click',clearFilters);
for(const [id,delta] of [['page-prev',-1],['page-next',1]])$(id).addEventListener('click',()=>{state.page+=delta;renderCards();$('explore-title').tabIndex=-1;$('explore-title').focus({preventScroll:true});$('explore-title').scrollIntoView({block:'start',behavior:'instant'});});
$('route-uf').addEventListener('change',e=>{state.routeUf=e.target.value;renderRoute();});
document.addEventListener('click',async event=>{const territory=event.target.closest('[data-territory]');if(territory){setTerritory(territory.dataset.territory);return;}const filter=event.target.closest('[data-filter]');if(filter){state[filter.dataset.filter]=filter.dataset.value;changed();return;}const favorite=event.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);saveFavorites();renderCards();renderSaved();announceApp(`${byId.get(id).title} ${state.favorites.has(id)?'salvo nos':'removido dos'} favoritos.`);return;}const route=event.target.closest('[data-route-area]');if(route){state.routeArea=route.dataset.routeArea;renderRouteOptions();renderRoute();announceApp(`Rota de ${state.routeArea} criada. O resultado está depois das opções.`);return;}if(event.target.id==='print-route'){window.print();return;}if(event.target.id==='copy-route'){const text=`Minha rota em ${state.routeArea}\n${chooseRoute(state.routeArea).map((r,i)=>`${i+1}. ${r.title}: ${r.url}`).join('\n')}`;try{if(!await RotaPlanner.copy(text))throw Error("Cópia indisponível");event.target.textContent='Rota copiada!';announceApp('Rota copiada.');}catch{event.target.textContent='Não foi possível copiar';announceApp('Não foi possível copiar a rota.');}setTimeout(()=>{if($('copy-route'))$('copy-route').textContent='Copiar rota';},2200);}});
renderCards();renderSaved();renderRouteOptions();
